import sys

# Increase recursion depth to handle deep trees in DSU
sys.setrecursionlimit(2000000)

def solve():
    # Read all input at once
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T_str = next(iterator)
        T = int(T_str)
    except StopIteration:
        return

    MOD = 998244353

    for _ in range(T):
        try:
            H = int(next(iterator))
            W = int(next(iterator))
        except StopIteration:
            break

        grid = []
        for _ in range(H):
            grid.append(next(iterator))

        # Check parity of 'A' in each row and column
        row_a_count = [0] * H
        col_a_count = [0] * W

        for r in range(H):
            for c in range(W):
                if grid[r][c] == 'A':
                    row_a_count[r] += 1
                    col_a_count[c] += 1

        possible = True
        for r in range(H):
            if row_a_count[r] % 2 != 0:
                possible = False
                break
        if possible:
            for c in range(W):
                if col_a_count[c] % 2 != 0:
                    possible = False
                    break

        if not possible:
            print(0)
            continue

        # DSU initialization
        # Nodes 0..W-1 for columns, W..W+H-1 for rows
        num_nodes = W + H
        parent = list(range(num_nodes))
        xor_val = [0] * num_nodes
        components = num_nodes

        def find(i):
            if parent[i] != i:
                root = find(parent[i])
                xor_val[i] ^= xor_val[parent[i]]
                parent[i] = root
            return parent[i]

        def union(u, v, w):
            nonlocal components
            root_u = find(u)
            root_v = find(v)

            if root_u != root_v:
                parent[root_u] = root_v
                xor_val[root_u] = xor_val[u] ^ xor_val[v] ^ w
                components -= 1
                return True
            else:
                if (xor_val[u] ^ xor_val[v]) != w:
                    return False
                return True

        # col_prefix[j] stores XOR sum of A[k][j] for 0 <= k < i
        col_prefix = [0] * W
        first_row_A = [0] * W

        for i in range(H):
            row_str = grid[i]
            if i == 0:
                for j in range(W):
                    first_row_A[j] = 1 if row_str[j] == 'A' else 0

            row_prefix = 0
            first_char_val = 1 if row_str[0] == 'A' else 0

            for j in range(W):
                val = 1 if row_str[j] == 'A' else 0

                if row_str[j] == 'B':
                    term_col = 0
                    if i > 0:
                        term_col = col_prefix[j] ^ first_row_A[j]

                    term_row = 0
                    if j > 0:
                        term_row = row_prefix ^ first_char_val

                    weight = term_col ^ term_row

                    u = j
                    v = W + i

                    if not union(u, v, weight):
                        possible = False
                        break

                col_prefix[j] ^= val
                row_prefix ^= val

            if not possible:
                break

        if possible:
            ans = pow(2, components, MOD)
            print(ans)
        else:
            print(0)

