class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(n):
            if n == 0:
                return 0

            digits = [int(d) for d in str(n)]
            num_digits = len(digits)
            total = 0

            # Count numbers without '0' where product % sum == 0
            # Maximum digit sum for n < 10^9 is 81 (for 999,999,999)
            for target_sum in range(1, 82):
                total += self._count_with_sum_and_product(digits, target_sum)

            # Count numbers with '0' (all are beautiful since product = 0, divisible by any sum)
            total_without_zero = self._count_all_without_zero(digits)
            total += (n - total_without_zero)

            return total

        return count(r) - count(l - 1)

    def _count_with_sum_and_product(self, digits, target_sum):
        """Count numbers <= n with digit sum = target_sum and product % target_sum == 0 (without '0')"""
        n = len(digits)
        memo = {}

        def dp(idx, current_sum, current_product_mod, tight, leading_zeros):
            # Pruning: if current_sum already exceeds target_sum, return 0
            if current_sum > target_sum:
                return 0

            # Base case: reached end of digits
            if idx == n:
                # Only count if we placed at least one non-zero digit
                if leading_zeros:
                    return 0  # No valid number placed
                if current_sum != target_sum:
                    return 0  # Sum doesn't match target_sum
                return 1 if current_product_mod == 0 else 0

            state = (idx, current_sum, current_product_mod, tight, leading_zeros)
            if state in memo:
                return memo[state]

            limit = digits[idx] if tight else 9
            res = 0

            # Option 1: Skip this position if we're still in leading zeros
            # This allows counting numbers with fewer digits than n
            if leading_zeros:
                res += dp(idx + 1, 0, 1, tight, True)

            # Option 2: Place a non-zero digit (1-9)
            for d in range(1, 10):
                if current_sum + d > target_sum:
                    break

                new_tight = tight and (d == limit)
                new_product_mod = (current_product_mod * d) % target_sum
                res += dp(idx + 1, current_sum + d, new_product_mod, new_tight, False)

            memo[state] = res
            return res

        return dp(0, 0, 1, True, True)

    def _count_all_without_zero(self, digits):
        """Count all numbers <= n without digit '0'"""
        n = len(digits)
        memo = {}

        def dp(idx, current_sum, tight, leading_zeros):
            if idx == n:
                return 1 if not leading_zeros else 0

            state = (idx, current_sum, tight, leading_zeros)
            if state in memo:
                return memo[state]

            limit = digits[idx] if tight else 9
            res = 0

            # Skip position if leading zeros
            if leading_zeros:
                res += dp(idx + 1, 0, tight, True)

            # Place non-zero digit (1-9)
            for d in range(1, 10):
                if d > limit and tight:
                    break
                new_tight = tight and (d == limit)
                res += dp(idx + 1, current_sum + d, new_tight, False)

            memo[state] = res
            return res

        return dp(0, 0, True, True)

