    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))
        adj[v].append((u, w))

    visited = [False] * (N + 1)
    dist = [0] * (N + 1)
    ans = [0] * (N + 1)

    for i in range(1, N + 1):
        if not visited[i]:
            # Start BFS/DFS for component
            stack = [i]
            visited[i] = True
            dist[i] = 0
            component_nodes = [i]

            while stack:
                u = stack.pop()
                for v, w in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        dist[v] = dist[u] ^ w
                        component_nodes.append(v)
                        stack.append(v)
                    else:
                        # Check consistency
                        if dist[u] ^ dist[v] != w:
                            print("-1")
                            return

            # Calculate optimal root value for this component
            bit_counts = [0] * 31

            for u in component_nodes:
                d = dist[u]
                for k in range(31):
                    if (d >> k) & 1:
                        bit_counts[k] += 1

            root_val = 0
            for k in range(31):
                # If more than half have bit k set, set bit k in root_val
                if bit_counts[k] > len(component_nodes) // 2:
                    root_val |= (1 << k)

            # Assign answers
            for u in component_nodes:
                ans[u] = root_val ^ dist[u]

    # Output result
    print(*(ans[1:]))

