class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        length = n + m - 1

        # Array to store the result, initialized with None
        result = [None] * length

        # Track which positions are forced by 'T' constraints
        forced = [False] * length

        # Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if pos < length:
                        if result[pos] is not None and result[pos] != str2[j]:
                            return ""  # Conflict in 'T' constraints
                        result[pos] = str2[j]
                        forced[pos] = True

        # Fill unforced positions with 'a' (lexicographically smallest)
        for i in range(length):
            if not forced[i]:
                result[i] = 'a'

        # Check 'F' constraints and fix violations
        for i in range(n):
            if str1[i] == 'F':
                # Check if this window matches str2
                matches = True
                for j in range(m):
                    if result[i + j] != str2[j]:
                        matches = False
                        break

                if matches:
                    # Need to change one character to break the match
                    # Find the rightmost position that is not forced
                    changed = False
                    for j in range(m - 1, -1, -1):
                        pos = i + j
                        if not forced[pos]:
                            # Change this character to break the match
                            # To minimize lexicographically, pick 'a' if str2[j] != 'a', else 'b'
                            if str2[j] == 'a':
                                result[pos] = 'b'
                            else:
                                result[pos] = 'a'
                            changed = True
                            break

                    if not changed:
                        # All positions in this window are forced, can't break the match
                        return ""

        return ''.join(result)

