class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)

        # Helper function to calculate Manhattan distance
        def manhattan_distance(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        # Binary search on the answer
        low = 0
        high = 2 * side
        ans = 0

        while low <= high:
            mid = (low + high) // 2
            if mid == 0:
                ans = max(ans, mid)
                low = mid + 1
                continue

            if self.can_select(points, k, mid, manhattan_distance):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans

    def can_select(self, points: List[List[int]], k: int, D: int, manhattan_distance) -> bool:
        n = len(points)

        # Edge case: if k <= 1, always possible
        if k <= 1:
            return True

        # Backtracking to select k points with pairwise distance >= D
        selected = []

        def backtrack(idx, count):
            # Pruning: if we can't possibly select k points from remaining
            if count + (n - idx) < k:
                return False

            # Base case: we've selected k points
            if count == k:
                return True

            # Try to select points from idx onwards
            for i in range(idx, n):
                # Check if point i is at distance >= D from all selected points
                valid = True
                for p in selected:
                    if manhattan_distance(points[i], p) < D:
                        valid = False
                        break

                if valid:
                    selected.append(points[i])
                    if backtrack(i + 1, count + 1):
                        return True
                    selected.pop()

            return False

        return backtrack(0, 0)

