    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])

        # Directions: 0: (1, 1), 1: (1, -1), 2: (-1, -1), 3: (-1, 1)
        # Clockwise turn: D -> (D + 1) % 4
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # Len[r][c][D] stores the length of the longest valid sequence ending at (r, c) in direction D
        Len = [[[0] * 4 for _ in range(m)] for _ in range(n)]

        # StartLen[r][c][D] stores the length of the longest valid sequence starting at (r, c) in direction D
        # The phase is implicitly determined by grid[r][c]
        StartLen = [[[0] * 4 for _ in range(m)] for _ in range(n)]

        # Sequence values: 1, 2, 0, 2, 0, ...
        # S[k] = 1 if k % 3 == 0, 2 if k % 3 == 1, 0 if k % 3 == 2
        def get_val(k):
            rem = k % 3
            if rem == 0: return 1
            elif rem == 1: return 2
            else: return 0

        # Compute Len
        # For D=0 (1, 1): iterate r, c increasing
        for r in range(n):
            for c in range(m):
                dr, dc = dirs[0]
                prev_r, prev_c = r - dr, c - dc
                if prev_r >= 0 and prev_c >= 0:
                    prev_len = Len[prev_r][prev_c][0]
                    if prev_len > 0:
                        # Check if grid[r][c] matches S[prev_len]
                        if grid[r][c] == get_val(prev_len):
                            Len[r][c][0] = prev_len + 1
                        else:
                            Len[r][c][0] = 0
                    else:
                        Len[r][c][0] = 0
                if grid[r][c] == 1:
                    Len[r][c][0] = max(Len[r][c][0], 1)

        # For D=1 (1, -1): iterate r increasing, c decreasing
        for r in range(n):
            for c in range(m - 1, -1, -1):
                dr, dc = dirs[1]
                prev_r, prev_c = r - dr, c - dc
                if prev_r >= 0 and prev_c >= 0:
                    prev_len = Len[prev_r][prev_c][1]
                    if prev_len > 0:
                        if grid[r][c] == get_val(prev_len):
                            Len[r][c][1] = prev_len + 1
                        else:
                            Len[r][c][1] = 0
                    else:
                        Len[r][c][1] = 0
                if grid[r][c] == 1:
                    Len[r][c][1] = max(Len[r][c][1], 1)

        # For D=2 (-1, -1): iterate r decreasing, c increasing
        for r in range(n - 1, -1, -1):
            for c in range(m):
                dr, dc = dirs[2]
                prev_r, prev_c = r - dr, c - dc
                if prev_r >= 0 and prev_c >= 0:
                    prev_len = Len[prev_r][prev_c][2]
                    if prev_len > 0:
                        if grid[r][c] == get_val(prev_len):
                            Len[r][c][2] = prev_len + 1
                        else:
                            Len[r][c][2] = 0
                    else:
                        Len[r][c][2] = 0
                if grid[r][c] == 1:
                    Len[r][c][2] = max(Len[r][c][2], 1)

        # For D=3 (-1, 1): iterate r decreasing, c decreasing
        for r in range(n - 1, -1, -1):
            for c in range(m - 1, -1, -1):
                dr, dc = dirs[3]
                prev_r, prev_c = r - dr, c - dc
                if prev_r >= 0 and prev_c >= 0:
                    prev_len = Len[prev_r][prev_c][3]
                    if prev_len > 0:
                        if grid[r][c] == get_val(prev_len):
                            Len[r][c][3] = prev_len + 1
                        else:
                            Len[r][c][3] = 0
                    else:
                        Len[r][c][3] = 0
                if grid[r][c] == 1:
                    Len[r][c][3] = max(Len[r][c][3], 1)

        # Compute StartLen
        # For D=0 (1, 1): iterate r, c decreasing
        for r in range(n - 1, -1, -1):
            for c in range(m - 1, -1, -1):
                dr, dc = dirs[0]
                next_r, next_c = r + dr, c + dc
                if next_r < n and next_c < m:
                    # Determine phase p for grid[r][c]
                    # grid[r][c] == S[p]
                    # p = 0 if 1, 1 if 2, 2 if 0
                    val = grid[r][c]
                    if val == 1: p = 0
                    elif val == 2: p = 1
                    else: p = 2

                    # Next value should be S[(p+1)%3]
                    next_val = get_val(p + 1)
                    if grid[next_r][next_c] == next_val:
                        StartLen[r][c][0] = 1 + StartLen[next_r][next_c][0]
                    else:
                        StartLen[r][c][0] = 1
                else:
                    val = grid[r][c]
                    if val == 1: p = 0
                    elif val == 2: p = 1
                    else: p = 2
                    StartLen[r][c][0] = 1

        # For D=1 (1, -1): iterate r decreasing, c increasing
        for r in range(n - 1, -1, -1):
            for c in range(m):
                dr, dc = dirs[1]
                next_r, next_c = r + dr, c + dc
                if next_r < n and next_c < m:
                    val = grid[r][c]
                    if val == 1: p = 0
                    elif val == 2: p = 1
                    else: p = 2
                    next_val = get_val(p + 1)
                    if grid[next_r][next_c] == next_val:
                        StartLen[r][c][1] = 1 + StartLen[next_r][next_c][1]
                    else:
                        StartLen[r][c][1] = 1
                else:
                    val = grid[r][c]
                    if val == 1: p = 0
                    elif val == 2: p = 1
                    else: p = 2
                    StartLen[r][c][1] = 1

        # For D=2 (-1, -1): iterate r increasing, c decreasing
        for r in range(n):
            for c in range(m - 1, -1, -1):
                dr, dc = dirs[2]
                next_r, next_c = r + dr, c + dc
                if next_r < n and next_c < m:
                    val = grid[r][c]
                    if val == 1: p = 0
                    elif val == 2: p = 1
                    else: p = 2
                    next_val = get_val(p + 1)
                    if grid[next_r][next_c] == next_val:
                        StartLen[r][c][2] = 1 + StartLen[next_r][next_c][2]
                    else:
                        StartLen[r][c][2] = 1
                else:
                    val = grid[r][c]
                    if val == 1: p = 0
                    elif val == 2: p = 1
                    else: p = 2
                    StartLen[r][c][2] = 1

        # For D=3 (-1, 1): iterate r increasing, c increasing
        for r in range(n):
            for c in range(m):
                dr, dc = dirs[3]
                next_r, next_c = r + dr, c + dc
                if next_r < n and next_c < m:
                    val = grid[r][c]
                    if val == 1: p = 0
                    elif val == 2: p = 1
                    else: p = 2
                    next_val = get_val(p + 1)
                    if grid[next_r][next_c] == next_val:
                        StartLen[r][c][3] = 1 + StartLen[next_r][next_c][3]
                    else:
                        StartLen[r][c][3] = 1
                else:
                    val = grid[r][c]
                    if val == 1: p = 0
                    elif val == 2: p = 1
                    else: p = 2
                    StartLen[r][c][3] = 1

        ans = 0
        for r in range(n):
            for c in range(m):
                for d in range(4):
                    if Len[r][c][d] > 0:
                        ans = max(ans, Len[r][c][d])
                        # Check for V-shape
                        d_out = (d + 1) % 4
                        l_in = Len[r][c][d]
                        # The phase of the turn cell is (l_in - 1) % 3
                        # This is consistent with grid[r][c]
                        l_out = StartLen[r][c][d_out]
                        if l_out > 0:
                            ans = max(ans, l_in + l_out - 1)

        return ans

class Solution:
    def countSubstrings(self, s: str) -> int:
        total = 0
        # rem[k][r] stores the count of substrings ending at the previous position
        # with value % k == r
        # k ranges from 1 to 9
        rem = [[0] * k for k in range(10)]
        new_rem = [[0] * k for k in range(10)]

        for char in s:
            d = int(char)

            for k in range(1, 10):
                # Update existing remainders: val' = val * 10 + d
                for r in range(k):
                    new_rem[k][(r * 10 + d) % k] += rem[k][r]
                # Add the new single digit substring
                new_rem[k][d % k] += 1

            # Swap buffers
            rem, new_rem = new_rem, rem

            # Clear new_rem for next iteration
            for k in range(1, 10):
                for r in range(k):
                    new_rem[k][r] = 0

            if d != 0:
                total += rem[d][0]

        return total

