        for p in primes:
            if p * p > temp:
                break
            if temp % p == 0:
                prime_factors.append(p)
                while temp % p == 0:
                    temp //= p
        if temp > 1:
            prime_factors.append(temp)

        # Search for A directly
        # We need A^N == 1 (mod M) and A^(N/p) != 1 (mod M) for all p in prime_factors
        A = -1
        limit = 100000
        for cand in range(2, limit + 1):
            if pow(cand, N, M) == 1:
                valid = True
                for p in prime_factors:
                    if pow(cand, N // p, M) == 1:
                        valid = False
                        break
                if valid:
                    A = cand
                    break

        out.append(f"{A} {M}")

    sys.stdout.write('\n'.join(out) + '\n')

