        if not items[v]:
            dp_tables.append([0] * (X + 1))
            continue

        # Optimization: Group by cost and keep top X/c items
        # This reduces the number of items processed if there are many items with the same cost
        by_cost = {}
        for a, c in items[v]:
            if c not in by_cost:
                by_cost[c] = []
            by_cost[c].append(a)

        optimized_items = []
        for c, vals in by_cost.items():
            vals.sort(reverse=True)
            limit = X // c
            # Keep at most limit items (since we can pick at most X/c items of cost c)
            if len(vals) > limit:
                optimized_items.extend([(vals[i], c) for i in range(limit)])
            else:
                optimized_items.extend([(a, c) for a in vals])

        # Knapsack DP
        # dp[j] will store max vitamins with cost <= j
        dp = [0] * (X + 1)

        for a, c in optimized_items:
            # Standard 0/1 knapsack: iterate from X down to c
            for j in range(X, c - 1, -1):
                if dp[j-c] + a > dp[j]:
                    dp[j] = dp[j-c] + a

        dp_tables.append(dp)

    # Binary search for the answer
    # The maximum possible answer is bounded by the max vitamins we can get for each type
    max_vitamins = [dp_tables[0][X], dp_tables[1][X], dp_tables[2][X]]
    upper_bound = min(max_vitamins)

    low = 0
    high = upper_bound
    ans = 0

    # Helper to find min cost for a given vitamin amount K
    # Since dp is non-decreasing, we can binary search for the smallest c such that dp[c] >= K
    def find_min_cost(dp, K):
        if dp[X] < K:
            return float('inf')
        l, r = 0, X
        res = X
        while l <= r:
            mid = (l + r) // 2
            if dp[mid] >= K:
                res = mid
                r = mid - 1
            else:
                l = mid + 1
        return res

    while low <= high:
        mid = (low + high) // 2
        c1 = find_min_cost(dp_tables[0], mid)
        c2 = find_min_cost(dp_tables[1], mid)
        c3 = find_min_cost(dp_tables[2], mid)

        if c1 + c2 + c3 <= X:
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    print(ans)

