class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        # Extract all contiguous run lengths from the input string s
        run_lengths = []
        if not s:
            return 0

        current_char = s[0]
        current_length = 1

        for i in range(1, len(s)):
            if s[i] == current_char:
                current_length += 1
            else:
                run_lengths.append(current_length)
                current_char = s[i]
                current_length = 1

        # Don't forget the last run
        run_lengths.append(current_length)

        # Binary search for the minimum possible length
        left, right = 1, max(run_lengths)
        result = right

        while left <= right:
            mid = (left + right) // 2
            cost = 0
            for length in run_lengths:
                cost += length // (mid + 1)

            if cost <= numOps:
                result = mid
                right = mid - 1
            else:
                left = mid + 1

        return result

