        prefix_counts = [Counter() for _ in range(n + 1)]
        suffix_counts = [Counter() for _ in range(n + 1)]

        for i in range(1, n + 1):
            prefix_counts[i] = prefix_counts[i - 1].copy()
            prefix_counts[i][nums[i - 1]] += 1

        for i in range(n - 1, -1, -1):
            suffix_counts[i] = suffix_counts[i + 1].copy()
            suffix_counts[i][nums[i]] += 1

        result = 0

        # For each element as middle element (index 2 in subsequence)
        for i in range(n):
            mid_val = nums[i]
            left_count = prefix_counts[i][mid_val]
            right_count = suffix_counts[i + 1][mid_val]
            left_total = i
            right_total = n - 1 - i
            left_non_mid = left_total - left_count
            right_non_mid = right_total - right_count

            # Helper function for combinations
            def nCr(n, r):
                if r < 0 or r > n:
                    return 0
                if r == 0 or r == n:
                    return 1
                if r > n // 2:
                    r = n - r
                res = 1
                for k in range(r):
                    res = res * (n - k) // (k + 1)
                return res

            # Case 1: Middle element appears 3 times in subsequence
            ways3 = 0

            # 2 from left, 0 from right (2 M from left, 1 non-M from right)
            if left_count >= 2 and right_non_mid >= 1:
                ways3 = (ways3 + nCr(left_count, 2) * right_non_mid) % MOD

            # 0 from left, 2 from right (2 M from right, 1 non-M from left)
            if right_count >= 2 and left_non_mid >= 1:
                ways3 = (ways3 + nCr(right_count, 2) * left_non_mid) % MOD

            # 1 from left, 1 from right (1 M from each, 1 non-M from each)
            if left_count >= 1 and right_count >= 1 and left_non_mid >= 1 and right_non_mid >= 1:
                ways3 = (ways3 + left_count * right_count * left_non_mid * right_non_mid) % MOD

            # Case 2: Middle element appears 4 times in subsequence
            ways4 = 0

            # 3 from left, 0 from right (3 M from left, 1 non-M from right)
            if left_count >= 3 and right_non_mid >= 1:
                ways4 = (ways4 + nCr(left_count, 3) * right_non_mid) % MOD

            # 0 from left, 3 from right (3 M from right, 1 non-M from left)
            if right_count >= 3 and left_non_mid >= 1:
                ways4 = (ways4 + nCr(right_count, 3) * left_non_mid) % MOD

            # 2 from left, 1 from right (2 M from left, 1 M from right, 1 non-M from each)
            if left_count >= 2 and right_count >= 1 and left_non_mid >= 1 and right_non_mid >= 1:
                ways4 = (ways4 + nCr(left_count, 2) * right_count * left_non_mid * right_non_mid) % MOD

            # 1 from left, 2 from right (1 M from left, 2 M from right, 1 non-M from each)
            if left_count >= 1 and right_count >= 2 and left_non_mid >= 1 and right_non_mid >= 1:
                ways4 = (ways4 + left_count * nCr(right_count, 2) * left_non_mid * right_non_mid) % MOD

            # Case 3: Middle element appears 5 times in subsequence
            ways5 = 0

            # 3 from left, 1 from right (3 M from left, 1 M from right)
            if left_count >= 3 and right_count >= 1:
                ways5 = (ways5 + nCr(left_count, 3) * right_count) % MOD

            # 1 from left, 3 from right (1 M from left, 3 M from right)
            if left_count >= 1 and right_count >= 3:
                ways5 = (ways5 + left_count * nCr(right_count, 3)) % MOD

            # Case 4: Middle element appears exactly 2 times in subsequence
            ways2 = 0

            # 1 from left, 0 from right (1 M from left, 1 non-M from left, 2 non-M from right)
            if left_count >= 1 and left_non_mid >= 1 and right_non_mid >= 2:
                # Count ways to choose 2 non-M from right that don't include the chosen non-M from left
                # For each non-M from left, count valid pairs from right
