                valid_pairs = 0
                for v_left in left_non_mid_set:
                    # Count non-M from right that are not v_left
                    right_valid_count = 0
                    for v_right, cR in suffix_counts[i + 1].items():
                        if v_right != mid_val and v_right != v_left:
                            right_valid_count += cR

                    if right_valid_count >= 2:
                        valid_pairs = (valid_pairs + right_valid_count * (right_valid_count - 1) // 2) % MOD

                ways2 = (ways2 + left_count * left_non_mid * valid_pairs) % MOD

            # 0 from left, 1 from right (2 non-M from left, 1 M from right, 1 non-M from right)
            if right_count >= 1 and left_non_mid >= 2 and right_non_mid >= 1:
                # Count ways to choose 2 non-M from left that don't include the chosen non-M from right
                right_non_mid_set = set()
                for v, cR in suffix_counts[i + 1].items():
                    if v != mid_val:
                        right_non_mid_set.add(v)

                valid_pairs = 0
                for v_right in right_non_mid_set:
