                    left_valid_count = 0
                    for v_left, cL in prefix_counts[i].items():
                        if v_left != mid_val and v_left != v_right:
                            left_valid_count += cL

                    if left_valid_count >= 2:
                        valid_pairs = (valid_pairs + left_valid_count * (left_valid_count - 1) // 2) % MOD

                ways2 = (ways2 + right_count * right_non_mid * valid_pairs) % MOD

            result = (result + ways3 + ways4 + ways5 + ways2) % MOD

        return result

