class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size *= 2
        self.tree_min = [float('inf')] * (2 * self.size)
        self.tree_max = [float('-inf')] * (2 * self.size)

        # Build the tree
        for i in range(self.n):
            self.tree_min[self.size + i] = data[i]
            self.tree_max[self.size + i] = data[i]

        for i in range(self.size - 1, 0, -1):
            self.tree_min[i] = min(self.tree_min[2*i], self.tree_min[2*i+1])
            self.tree_max[i] = max(self.tree_max[2*i], self.tree_max[2*i+1])

    def query_first_ge(self, l, r, val):
        """Find the smallest index i in [l, r] such that tree[i] >= val."""
        l += self.size
        r += self.size
        while l <= r:
            if l % 2 == 1:
                if self.tree_max[l] >= val:
                    return l - self.size
                l += 1
            if r % 2 == 0:
                if self.tree_max[r] >= val:
                    return r - self.size
                r -= 1
            l //= 2
            r //= 2
        return -1

    def query_last_le(self, l, r, val):
        """Find the largest index i in [l, r] such that tree[i] <= val."""
        l += self.size
        r += self.size
        while l <= r:
            if l % 2 == 0:
                if self.tree_min[l] <= val:
                    return l - self.size
                l += 1
            if r % 2 == 1:
                if self.tree_min[r] <= val:
                    return r - self.size
                r -= 1
            l //= 2
            r //= 2
        return -1

