                idx = st_min_D.query_last_le(1, K - 1, Suf[mid+1])
                if idx == -1:
                    L_min = K
                else:
                    L_min = idx + 1

            # Find R_max(L_min)
            # R_max(L) is the largest R such that max(E[K+1..R]) < Suf[1] - Suf[L]
            # If K+1 > N, then R_max = K
            if K + 1 > N:
                R_max = K
            else:
                val = Suf[1] - Suf[L_min]
                idx = st_max_E.query_first_ge(K + 1, N, val)
                if idx == -1:
                    R_max = N
                else:
                    R_max = idx - 1

            if R_max >= mid:
                ans_R = mid
                low = mid + 1
            else:
                high = mid - 1

        R = ans_R
        if K - 1 < 1:
            L = K
        else:
            idx = st_min_D.query_last_le(1, K - 1, Suf[R+1])
            if idx == -1:
                L = K
            else:
                L = idx + 1

        ans = Suf[L] - Suf[R+1]
        results.append(str(ans))

    print(" ".join(results))

