    solve()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # DSU initialization
        parent = list(range(threshold + 1))
        rank = [0] * (threshold + 1)

        def find(i):
            root = i
            while parent[root] != root:
                root = parent[root]
            # Path compression
            curr = i
            while curr != root:
                nxt = parent[curr]
                parent[curr] = root
                curr = nxt
            return root

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                if rank[root_i] < rank[root_j]:
                    parent[root_i] = root_j
                elif rank[root_i] > rank[root_j]:
                    parent[root_j] = root_i
                else:
                    parent[root_i] = root_j
                    rank[root_j] += 1

        # Filter numbers <= threshold
        small_nums = [x for x in nums if x <= threshold]
        count_greater = len(nums) - len(small_nums)

        # first_node[m] stores the first number from small_nums that divides m
        first_node = [-1] * (threshold + 1)

        for x in small_nums:
            for m in range(x, threshold + 1, x):
                if first_node[m] == -1:
                    first_node[m] = x
                else:
                    union(first_node[m], x)

        # Count components for small_nums
        roots = set()
        for x in small_nums:
            roots.add(find(x))

        return len(roots) + count_greater
